import {audioClips} from './clips.js';
import {uid} from '../document/model.js';
export class AudioEngine{constructor(app){this.a=app;this.buffer=null;this.source=null;this.recording=false;this.generation=0;this.assetId=null;}
async context(resume=true){this.ctx||=new (globalThis.AudioContext||globalThis.webkitAudioContext)();if(resume&&this.ctx.state==='suspended')await this.ctx.resume();return this.ctx;}
async load(){const meta=this.a.doc.audio;if(!meta){this.buffer=null;this.assetId=null;return;}if(this.assetId===meta.assetId&&this.buffer)return;const blob=this.a.assets.get(meta.assetId);if(!blob)throw Error('Audio asset is missing.');const ctx=await this.context(false),id=meta.assetId,buffer=await ctx.decodeAudioData(await blob.arrayBuffer());if(this.a.doc.audio?.assetId!==id)return;this.buffer=buffer;this.assetId=id;this.a.timeline?.waveform();}
stop(){this.generation++;try{for(const source of this.sources||[])try{source.stop();source.disconnect();}catch{}this.sources=[];this.source?.stop();}catch{}this.source?.disconnect();this.source=null;this.gain?.disconnect();}
async start(time,destination){this.stop();const generation=this.generation,ctx=await this.context();if(generation!==this.generation)return false;await this.load();if(generation!==this.generation)return false;const a=this.a.doc.audio;this.origin=ctx.currentTime;this.timelineStart=time;if(!a||!this.buffer||a.muted)return;this.sources=[];for(const clip of audioClips(a)){const elapsed=time-clip.offset,length=clip.trimEnd-clip.trimStart;if(elapsed>=length)continue;const when=ctx.currentTime+Math.max(0,-elapsed),offset=clip.trimStart+Math.max(0,elapsed),duration=Math.max(0,clip.trimEnd-offset);if(!duration)continue;this.source=ctx.createBufferSource();this.source.buffer=this.buffer;this.gain=ctx.createGain();this.gain.gain.value=a.volume;this.source.connect(this.gain).connect(destination||ctx.destination);this.source.start(when,offset,duration);this.sources.push(this.source);}}
now(){return this.timelineStart+(this.ctx.currentTime-this.origin);}
async import(blob,name='Recording',projectId=this.a.doc.id){const ctx=await this.context(false),buffer=await ctx.decodeAudioData(await blob.arrayBuffer());if(this.a.doc.id!==projectId)throw Error('The project changed while audio was loading. Import it again.');const assetId=uid();this.a.assets.set(assetId,blob);this.a.mutate('Add audio',()=>{this.a.doc.audio={assetId,name,duration:buffer.duration,offset:this.a.time,trimStart:0,trimEnd:buffer.duration,volume:1,muted:false};},true);this.buffer=buffer;this.assetId=assetId;this.a.timeline.render();}
async record(){if(this.recording||this.pending||this.finalizing)return;this.pending=true;document.querySelector('#record').disabled=true;const projectId=this.a.doc.id;this.controls(true);try{if(!navigator.mediaDevices?.getUserMedia||!globalThis.MediaRecorder)throw Error('Microphone recording needs a secure browser connection with MediaRecorder support. Import an audio file instead.');const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(this.a.doc.id!==projectId){stream.getTracks().forEach(t=>t.stop());throw Error('Project changed while microphone permission was pending.');}try{const mime=['audio/mp4','audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus'].find(x=>MediaRecorder.isTypeSupported(x));const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{}),chunks=[];this.recorder=recorder;this.stream=stream;this.recording=true;this.recordStart=performance.now();this.recordOffset=this.a.time;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onerror=e=>{this.a.toast(e.error?.message||'Recording failed.');this.cleanup();};recorder.onstop=async()=>{const blob=new Blob(chunks,{type:recorder.mimeType});this.cleanup();this.finalizing=true;this.controls(true);try{if(this.a.doc.id!==projectId)throw Error('Recording belongs to a different project.');this.a.time=this.recordOffset;await this.import(blob,'Recording',projectId);}catch(e){this.a.toast('Could not decode recording: '+e.message);}finally{this.finalizing=false;this.controls(false);}};recorder.start(250);this.timer=setInterval(()=>{document.querySelector('#record-time').textContent=new Date(performance.now()-this.recordStart).toISOString().slice(14,19);},200);document.querySelector('#record').classList.add('recording');document.querySelector('#record').disabled=true;document.querySelector('#stop-record').disabled=false;}catch(e){stream.getTracks().forEach(t=>t.stop());throw e;}}finally{this.pending=false;if(!this.recording){this.controls(false);document.querySelector('#record').disabled=false;}}}
stopRecording(){if(this.recorder?.state==='recording')this.recorder.stop();}
controls(disabled){for(const id of ['project-menu','export','import-audio','audio-edit','play','audio-play','undo','redo'])document.querySelector('#'+id).disabled=disabled;}
cleanup(){this.controls(false);this.stream?.getTracks().forEach(t=>t.stop());clearInterval(this.timer);this.recording=false;document.querySelector('#record').classList.remove('recording');document.querySelector('#record').disabled=false;document.querySelector('#stop-record').disabled=true;}
async offline(p){const a=p.audio;if(!a||a.muted||!this.buffer)return null;const rate=48000,ctx=new OfflineAudioContext(2,Math.ceil(p.duration*rate),rate),source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=this.buffer;gain.gain.value=a.volume;source.connect(gain).connect(ctx.destination);for(const clip of audioClips(a)){if(clip.offset>=p.duration)continue;const part=ctx.createBufferSource();part.buffer=this.buffer;part.connect(gain);part.start(clip.offset,clip.trimStart,Math.min(clip.trimEnd-clip.trimStart,p.duration-clip.offset));}return ctx.startRendering();}
}
